insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f2', 'northline-1', 'demo-fund', 'northline', 3, 'sat', 'Market', 'HIGH', 'relationship-moat', '3:Market:relationship-moat', 'Retailer trust is the only moat', 'What a competitor cannot copy quickly is the trust of independent grocers, and the plan does not yet protect it with contracts.', array['nl-s1', 'nl-s5']::text[], 'open', null, null, '[]'::jsonb, 1);
insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f3', 'northline-1', 'demo-fund', 'northline', 4, 'dem', 'Market', 'MEDIUM', 'market-ceiling', '4:Market:market-ceiling', 'Independent grocer market is finite', 'The addressable base within 40 miles of one depot caps revenue well below the deck projection without a second site.', array['nl-s1']::text[], 'open', null, null, '[]'::jsonb, 2);
insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f4', 'northline-1', 'demo-fund', 'northline', 3, 'sat', 'Market', 'MEDIUM', 'regional-entrants', '3:Market:regional-entrants', 'Two regional operators could add chilled vans', 'Existing ambient couriers in Yorkshire could add refrigerated vehicles with modest capital.', '{}'::text[], 'open', null, null, '[]'::jsonb, 3);
insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f5', 'northline-1', 'demo-fund', 'northline', 1, 'exec', 'Financial', 'HIGH', 'drop-economics', '1:Financial:drop-economics', 'Every drop below 14 stops loses money', 'Revenue per drop averages below the fully loaded cost of a refrigerated van run. The deck assumes 18 stops per route from month four; actual density last quarter was 11.', array['nl-s2', 'nl-s3']::text[], 'open', null, null, '[]'::jsonb, 4);
insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f6', 'northline-1', 'demo-fund', 'northline', 1, 'fin', 'Financial', 'HIGH', 'runway', '1:Financial:runway', 'Base-case cash lasts nine months', 'At current burn the business reaches zero cash in month nine. A 10% price cut forced by a competitor cuts runway to six months.', array['nl-s2', 'nl-s3']::text[], 'open', null, null, '[]'::jsonb, 5);
insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f7', 'northline-1', 'demo-fund', 'northline', 1, 'fin', 'Financial', 'MEDIUM', 'upside-case', '1:Financial:upside-case', 'Upside case is not supported', 'Gross margin turns positive only above the 14-stop threshold. The upside case assumes it is reached by month five, which the evidence does not support.', array['nl-s3']::text[], 'open', null, null, '[]'::jsonb, 6);
insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f8', 'northline-1', 'demo-fund', 'northline', 1, 'fail', 'Financial', 'LOW', 'fuel-cost', '1:Financial:fuel-cost', 'Fuel cost exposure is unhedged', 'Diesel is roughly a fifth of route cost and no fuel surcharge clause is in the standard terms.', array['nl-s3', 'nl-s8']::text[], 'open', null, null, '[]'::jsonb, 7);
insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f9', 'northline-1', 'demo-fund', 'northline', 1, 'fin', 'Financial', 'LOW', 'payment-terms', '1:Financial:payment-terms', 'Retailers pay on 30-day terms', 'Thirty-day terms on small accounts add working capital strain as volume grows.', '{}'::text[], 'open', null, null, '[]'::jsonb, 8);
insert into public.findings (id, audit_id, org_id, company_id, agent, section, category, severity, topic, match_key, title, text, sources, status, owner, dismiss_reason, history, position) values ('northline-1-f10', 'northline-1', 'demo-fund', 'northline', 1, 'ops', 'Operational', 'HIGH', 'single-depot', '1:Operational:single-depot', 'One depot, no fallback', 'A single depot serves the whole region. A fault during a Friday run puts the weekend order cycle for every retailer at risk.', array['nl-s2', 'nl-s5']::text[], 'open', null, null, '[]'::jsonb, 9);
