insert into public.audits (id, org_id, company_id, date, status, trigger, score, raw_score, exposure, cap, base_directive, final_directive, overridden, override, override_cited, override_rejected, coverage, skipped_sections, orchestrator, model_version, prompt_version, calibration_version, snapshot_hash, source_ids, drift_flag, under_review, counted_against_usage, first_checkpoint, final_checkpoint, outcome_window_version, run_seconds) values ('northline-4', 'demo-fund', 'northline', '2026-10-14', 'complete', 'scheduled', 41, 41, '{"Market":58,"Financial":66,"Operational":64,"Competition":78,"Customer psychology":49,"Geographic":51,"Regulatory":37}'::jsonb, null, 'PIVOT', 'PIVOT', false, null, '{}'::text[], null, '{"agentsRun":6,"agentsTotal":6,"sectionsSkipped":1,"sectionsNotRun":[],"sourcesCited":8}'::jsonb, '[{"section":"ip","reason":"No proprietary technology or brand claims are made in the submitted material."}]'::jsonb, '{"rationale":"Demand is real. The delivery model loses money on every drop at current route density, and a funded national courier entered the Leeds corridor in September. Change pricing and route model before any further capital goes in.","investor":"The business has demand and a real customer base. The constraint is structural, so more capital would fund more loss-making routes. Funding should follow a density target, not precede it.","roadmap":"Days 0 to 30: reprice and cut sub-threshold routes. Days 30 to 90: sign annual agreements with the top five accounts. Day 90: re-audit. Move to PROCEED when density holds at 14 stops or more for eight weeks.","topRisks":["northline-4-f5","northline-4-f16","northline-4-f6"]}'::jsonb, '[PINNED MODEL VERSION]', 'prompts-2026.09', 'cal-2026.2', '10ade59e', array['nl-s1', 'nl-s2', 'nl-s3', 'nl-s4', 'nl-s5', 'nl-s6', 'nl-s7', 'nl-s8']::text[], false, false, true, '2027-10-14', '2028-10-14', 'ow-1', 252);
